// Vector source: crates/core/src/remote/testdata/e2e-vector.json (package A,
// generated by the Rust core; copied verbatim into ./testdata).
import { describe, expect, it } from "vitest";

import { OrkestrClient } from "../client";
import { b64uDecode, b64uEncode, fromUtf8, utf8 } from "./bytes";
import {
  DIR_C2D,
  DIR_D2C,
  DeviceHandshake,
  deriveSessionKeys,
  importVerifyKey,
  openRecord,
  sealRecord,
  transcriptHash,
  verifySig,
} from "./e2e";
import { codeMac, sas } from "./pairing";
import v from "./testdata/e2e-vector.json";
import { type RawSocket, createRemoteSocketFactory } from "./transport";

const B = b64uDecode;

async function importPrivate(d: string, pub: string, alg: "ECDSA" | "ECDH"): Promise<CryptoKeyPair> {
  const p = B(pub);
  const jwk = { kty: "EC", crv: "P-256", d, x: b64uEncode(p.slice(1, 33)), y: b64uEncode(p.slice(33, 65)) };
  const privateKey = await crypto.subtle.importKey("jwk", jwk, { name: alg, namedCurve: "P-256" }, false, [
    alg === "ECDSA" ? "sign" : "deriveBits",
  ]);
  const publicKey = await crypto.subtle.importKey("raw", p, { name: alg, namedCurve: "P-256" }, true,
    alg === "ECDSA" ? ["verify"] : []);
  return { privateKey, publicKey };
}

const rec = (dir: number) => v.records.find((r) => r.dir === dir)!;

describe("e2e-v1 against the core vector", () => {
  it("transcript hash, signatures, ECDH/HKDF and records match", async () => {
    const th = await transcriptHash(v.coreId, v.deviceId, B(v.ephDPublic), B(v.nonceD), v.ts, B(v.ephCPublic), B(v.nonceC));
    expect(b64uEncode(th)).toBe(v.transcriptHash);
    expect(await verifySig(await importVerifyKey(B(v.cikPublic)), B(v.serverHello.sig), th)).toBe(true);
    expect(await verifySig(await importVerifyKey(B(v.devicePublic)), B(v.clientFinish.sig), th)).toBe(true);

    const ephD = await importPrivate(v.ephDPrivate, v.ephDPublic, "ECDH");
    const { keys, raw } = await deriveSessionKeys(ephD.privateKey, B(v.ephCPublic), B(v.nonceD), B(v.nonceC), v.coreId, v.deviceId);
    expect(b64uEncode(raw.slice(0, 32))).toBe(v.kD2C);
    expect(b64uEncode(raw.slice(32))).toBe(v.kC2D);

    const d2c = rec(DIR_D2C);
    expect(b64uEncode(await sealRecord(keys.d2c, DIR_D2C, d2c.counter, utf8(d2c.plaintext)))).toBe(d2c.record);
    const c2d = rec(DIR_C2D);
    expect(fromUtf8(await openRecord(keys.c2d, DIR_C2D, 0, B(c2d.record)))).toBe(c2d.plaintext);
  });

  it("rejects tampered records, wrong counters and a forged serverHello", async () => {
    const ephD = await importPrivate(v.ephDPrivate, v.ephDPublic, "ECDH");
    const { keys } = await deriveSessionKeys(ephD.privateKey, B(v.ephCPublic), B(v.nonceD), B(v.nonceC), v.coreId, v.deviceId);
    const bad = B(rec(DIR_C2D).record);
    bad[bad.length - 1]! ^= 1;
    await expect(openRecord(keys.c2d, DIR_C2D, 0, bad)).rejects.toThrow();
    await expect(openRecord(keys.c2d, DIR_C2D, 1, B(rec(DIR_C2D).record))).rejects.toThrow(/counter/);

    const dk = await importPrivate(v.devicePrivate, v.devicePublic, "ECDSA");
    const hs = new DeviceHandshake({
      coreId: v.coreId, deviceId: v.deviceId, deviceKey: dk.privateKey, corePubKey: v.devicePublic, // wrong CIK
      ephemeral: ephD, nonce: B(v.nonceD), now: () => v.ts,
    });
    await hs.hello();
    await expect(hs.finish(v.serverHello as never)).rejects.toThrow(/signature/);
  });

  it("pairing codeMac / SAS are deterministic and bound to the inputs", async () => {
    const pub = B(v.devicePublic);
    const a = await codeMac("ABCD1234", pub, "p1");
    expect(a).toHaveLength(32);
    expect(b64uEncode(await codeMac("ABCD1234", pub, "p2"))).not.toBe(b64uEncode(a));
    const s = await sas(B(v.cikPublic), pub, "p1");
    expect(s).toMatch(/^\d{6}$/);
    expect(await sas(B(v.cikPublic), pub, "p1")).toBe(s);
  });
});

/** Fake gateway relay that plays the core side with the vector values. */
class FakeRelay implements RawSocket {
  readyState = 0;
  binaryType = "blob";
  sent: (string | Uint8Array)[] = [];
  onopen: ((ev: unknown) => void) | null = null;
  onmessage: ((ev: { data: unknown }) => void) | null = null;
  onclose: ((ev: { code: number; reason: string }) => void) | null = null;
  onerror: ((ev: unknown) => void) | null = null;
  constructor(readonly url: string) {
    setTimeout(() => {
      this.readyState = 1;
      this.onopen?.({});
    }, 0);
  }
  send(d: string | ArrayBuffer | Uint8Array) {
    this.sent.push(typeof d === "string" ? d : new Uint8Array(d as ArrayBuffer));
  }
  close(code = 1000, reason = "") {
    this.readyState = 3;
    this.onclose?.({ code, reason });
  }
  push(data: unknown) {
    this.onmessage?.({ data });
  }
}

const tick = () => new Promise((r) => setTimeout(r, 5));
async function until(cond: () => boolean) {
  for (let i = 0; i < 200 && !cond(); i++) await tick();
  expect(cond()).toBe(true);
}

describe("RemoteSocket over a fake relay", () => {
  async function setup(corePubKey = v.cikPublic) {
    const dk = await importPrivate(v.devicePrivate, v.devicePublic, "ECDSA");
    const ephD = await importPrivate(v.ephDPrivate, v.ephDPublic, "ECDH");
    let relay: FakeRelay | null = null;
    const errors: string[] = [];
    const factory = createRemoteSocketFactory({
      gatewayUrl: "http://127.0.0.1:8787",
      coreId: v.coreId,
      deviceId: v.deviceId,
      deviceKey: dk,
      corePubKey,
      rawSocket: (u) => (relay = new FakeRelay(u)),
      onHandshakeError: (c) => errors.push(c),
      handshake: { ephemeral: ephD, nonce: B(v.nonceD), now: () => v.ts },
    });
    return { factory, relay: () => relay!, errors };
  }

  it("does the handshake with exact vector frames, then seals/opens records", async () => {
    const { factory, relay } = await setup();
    const ws = factory("");
    expect(relay().url).toBe(`ws://127.0.0.1:8787/v1/connect?coreId=${v.coreId}`);
    const got: unknown[] = [];
    let opened = false;
    ws.onopen = () => (opened = true);
    ws.onmessage = (e) => got.push(e.data);
    await until(() => relay().sent.length === 1);
    expect(JSON.parse(relay().sent[0] as string)).toEqual(v.clientHello);
    relay().push(JSON.stringify(v.serverHello));
    await until(() => opened);
    const fin = JSON.parse(relay().sent[1] as string) as { t: string; sig: string };
    expect(fin.t).toBe("clientFinish");
    const th = B(v.transcriptHash);
    expect(await verifySig(await importVerifyKey(B(v.devicePublic)), B(fin.sig), th.buffer)).toBe(true);

    ws.send(rec(DIR_D2C).plaintext);
    await until(() => relay().sent.length === 3);
    expect(b64uEncode(relay().sent[2] as Uint8Array)).toBe(rec(DIR_D2C).record);
    relay().push(B(rec(DIR_C2D).record).buffer);
    await until(() => got.length === 1);
    expect(got[0]).toBe(rec(DIR_C2D).plaintext);
  });

  it("closes with 4401 on a core error frame and on a pinned-key mismatch", async () => {
    const a = await setup();
    const ws = a.factory("");
    let closed: { code: number; reason: string } | null = null;
    ws.onclose = (e) => (closed = e);
    await until(() => a.relay().sent.length === 1);
    a.relay().push(JSON.stringify({ t: "error", code: "revoked" }));
    await until(() => closed !== null);
    expect(closed!.code).toBe(4401);
    expect(a.errors).toEqual(["revoked"]);

    const b = await setup(v.devicePublic);
    const ws2 = b.factory("");
    let closed2 = false;
    ws2.onclose = () => (closed2 = true);
    await until(() => b.relay().sent.length === 1);
    b.relay().push(JSON.stringify(v.serverHello));
    await until(() => closed2);
    expect(b.errors[0]).toMatch(/signature/);
  });

  it("OrkestrClient works unchanged on top of the factory", async () => {
    const { factory, relay } = await setup();
    const client = new OrkestrClient("ws://ignored", "remote", { webSocket: factory, reconnect: false });
    const connecting = client.connect();
    await until(() => relay()?.sent.length === 1);
    relay().push(JSON.stringify(v.serverHello));
    await until(() => relay().sent.length === 3); // clientFinish + encrypted auth
    expect(typeof relay().sent[2]).not.toBe("string");
    // Core side: decrypt the auth frame with kD2C and answer with an encrypted auth result.
    const ephD = await importPrivate(v.ephDPrivate, v.ephDPublic, "ECDH");
    const { keys } = await deriveSessionKeys(ephD.privateKey, B(v.ephCPublic), B(v.nonceD), B(v.nonceC), v.coreId, v.deviceId);
    const auth = JSON.parse(fromUtf8(await openRecord(keys.d2c, DIR_D2C, 0, relay().sent[2] as Uint8Array))) as { type: string; id: string };
    expect(auth.type).toBe("auth");
    const coreKeys = await crypto.subtle.importKey("raw", B(v.kC2D), "AES-GCM", false, ["encrypt"]);
    const res = { type: "res", id: auth.id, ok: true, result: { serverVersion: "test", protocolVersion: 1 } };
    relay().push((await sealRecord(coreKeys, DIR_C2D, 0, utf8(JSON.stringify(res)))).buffer);
    await connecting;
    expect(client.state).toBe("open");
    client.close();
  });
});
